Dưới đây là phiên bản của đoạn Python đã được chuyển sang JavaScript (Node.js) với logic tương tự:

```javascript
const { countBy, sortBy, head } = require('lodash');

function topTu(vanBan, k = 3) {
    // Tách câu thành mảng từ và loại bỏ dấu chấm, phẩy, hỏi và感叹号
    const tu = vanBan.toLowerCase().match(/\b\w+\b/g);

    // Đếm các từ trong mảng từ
    const dem = countBy(tu || []);

    // Sắp xếp theo số lần xuất hiện giảm dần
    const topTen = sortBy(Object.keys(dem), k => -dem[k]).slice(0, k);

    return topTen.map(key => ({ key, count: dem[key] }));
}

console.log(topTu('Mèo ăn cá. Mèo ngủ. Chó ăn xương, mèo chơi!'));
```

Note: Để chạy đoạn code trên, bạn cần cài đặt lodash trước bằng lệnh `npm install lodash` hoặc `yarn add lodash`.
